@@ -1,12 +1,48 @@
+import fs from "fs";
+import path from "path";
+
 interface Entry {
   value: string;
   expiresAt: number;
 }

 const store = new Map<string, Entry>();
+const persistPath = process.env.SESSION_PERSIST_PATH || "/tmp/sessions.json";
+
+const loadFromDisk = (): void => {
+  try {
+    if (fs.existsSync(persistPath)) {
+      const data = fs.readFileSync(persistPath, "utf-8");
+      const entries: Record<string, Entry> = JSON.parse(data);
+      for (const [key, entry] of Object.entries(entries)) {
+        if (entry.expiresAt > Date.now()) {
+          store.set(key, entry);
+        }
+      }
+    }
+  } catch (err) {
+    console.error("Failed to load sessions from disk:", err);
+  }
+};
+
+const saveToDisk = (): void => {
+  try {
+    const dir = path.dirname(persistPath);
+    if (!fs.existsSync(dir)) {
+      fs.mkdirSync(dir, { recursive: true });
+    }
+    const entries = Object.fromEntries(store);
+    fs.writeFileSync(persistPath, JSON.stringify(entries), "utf-8");
+  } catch (err) {
+    console.error("Failed to save sessions to disk:", err);
+  }
+};
+
+loadFromDisk();

 export const put = (key: string, value: string, ttlMs: number): void => {
   store.set(key, { value, expiresAt: Date.now() + ttlMs });
+  saveToDisk();
 };

